%[text] # One Charged Plate and a Point Particle
clear;
% The variables
% a : angle of point in plate
% d : distance from plate to particle
% v : relative particle velocity [0...1]
% v_a: change in velocity due to aceleration v_a = a*Dt = a*R/C
% r : radial distance between axis to point in plate
syms a d v v_a r real positive;
assume(d>0)
assume(r>=0)
assume(v>=0)
assumeAlso (v < 1)
assume(a>=0)
taylorOrder = 9;

% Particle velocity
vp = [-v,0,0];
%%
%[text] ## The vectors
%[text] d= distance from the charge to the plate
%[text] r = radius of a circle in the plate
%[text] The speed of light is 1 (c=1)
%[text] 
R = (d^2+r^2)^(1/2) % total distance from a point in the plate to the charge %[output:523b8018]

% Get two points per circle. 
% a is the angle
vec_l1 = [d,r*cos(a),r*sin(a)]/R  % velocity vector of light from a point 1 in left positive plate at angle a %[output:249dd629]
simplify(dot(vec_l1,vec_l1)) %[output:6c66e062]
vec_l2 = [d,-r*cos(a),-r*sin(a)]/R  % velocity vector of light from a point 2 in left positive plate at 180+a %[output:86cc6466]
r_vec_l1 = (vec_l1 - vp) % left plate relative velocity of 1 particle (v in light speed fraction =v/c) %[output:7ae2b01a]
r_vec_l2 = (vec_l2 - vp) % left plate relative velocity of 2 particle (v in light speed fraction =v/c) %[output:232c894b]

%%
%[text] ## The Anomrality 
% 1 particle disparity between photon angle and trayectory
dprd_l1 = simplify(simplifyFraction(dot(vec_l1,vec_l1)/dot(vec_l1,r_vec_l1))) % Cosine^2 left plate %[output:6dfcff8b]



% 2 particle disparity between photon angle and trayectory
dprd_l2 = simplify(simplifyFraction(dot(vec_l2,vec_l2)/dot(vec_l2,r_vec_l2))) % Cosine^2 left plate %[output:6453804c]


%%
%[text] ## The Relative Net Force of the Two Points
% Force of the two point in plate and moving particle
dforce = ((dprd_l1/R^2)*vec_l1 + (dprd_l2/R^2)*vec_l2); % net Force in the x direction first points.
dforce = simplify(expand(dforce),'Steps',100) % Two charges %[output:96bd3cf5]
dforce_x = dforce(1) %[output:4ad33a13]
%dforce_x = simplify(taylor(expand(subs(dforce_x/2,v,v+v_a) + dforce_x/2),v_a,order=2))
%%
%[text] ## Check at v = 0, r =0
df_v_zero = simplify(subs(dforce_x,[v,r],[0,0]),'Steps',100) % Due to the two point charges %[output:634c51ae]
df_v_one = simplify(subs(dforce_x,[v,r],[v,0]),'Steps',100) % Due to the two point charges %[output:6f4ce4d6]
%%
%[text] ## Integrate all the angles
%dforce_xT = expand(taylor(dforce_x,v,Order=taylorOrder));
dforce_xT = dforce_x;

dcircle = int(dforce_xT,a,0,pi); % From zero to pi i.e., the full circle
%%
dcircle = simplify(dcircle,steps=100); % Net force of the two full circles with charge density
df_v_zero = simplify(subs(dcircle,[v,r],[v,0]),'Steps',100) % Net force of the full zero radius circle (point) %[output:1c18ebef]
%[text] ## 
%%
%[text] ## Integrate for all values of r

dtotf = (r*dcircle)/(2*pi)  %[output:79661a25]
dtotf = expand(taylor(dtotf,v,Order=taylorOrder)); % Taylor
totf = int(dtotf,r,0,r); % Add all the circles
totf = simplify(totf); % The force on a charge due a charge surface density

%%
%[text] ## Set the Plates Radius to Infinity
sympref('PolynomialDisplayStyle', 'ascend');
totfInf = simplify(limit(totf,r,Inf)) % Net force by plate charge density %[output:4bda4235]
%totfInf = subs(totfInf,v,-v)

%%
figure(1)
plotrange = [0,0.99];
fplot(totfInf,plotrange) %[output:7e8a5418]
hold on %[output:7e8a5418]
relEq = sqrt(1-v^2) %[output:12564930]
relEqApx = taylor(relEq,v,Order=taylorOrder) %[output:850618b3]
fplot(relEq,plotrange) %[output:7e8a5418]
fplot(relEqApx,plotrange) %[output:7e8a5418]
xlabel('v/c')  %[output:7e8a5418]
ylabel('ratio')  %[output:7e8a5418]
legend({'Force Carriers',"Lorentz Mass","Lorentz Apx"},'Location','northeast') %[output:7e8a5418]
hold off %[output:7e8a5418]



%[text] ## Set the Plates Radius to d
totf_d = simplify(limit(totf,r,d)) % Net force by plate charge density %[output:419c6881]
totf_dV0 = subs(totf_d,v=0) %[output:0bae4578]

totf_dRel = simplify(totf_d/totf_dV0) %[output:6ac4844b]
totf_dRel0 = subs(totf_dRel,v_a,0) %[output:1cac5cb3]

%%
%[text] ## Plots
figure(1)
plotrange = [0,0.99];
fplot(totfInf,plotrange) %[output:53381f60]
hold on %[output:53381f60]
relEq = sqrt(1-v^2) %[output:4e8df2fd]
relEqApx = taylor(relEq,v,Order=taylorOrder) %[output:06490a8f]
fplot(relEq,plotrange) %[output:53381f60]
fplot(relEqApx,plotrange) %[output:53381f60]
fplot(totf_dRel0,plotrange) %[output:53381f60]
xlabel('v/c')  %[output:53381f60]
ylabel('ratio')  %[output:53381f60]
legend({'Force Carriers',"Lorentz Mass","Lorentz Apx","Fd"},'Location','northeast') %[output:53381f60]
hold off %[output:53381f60]
%[text] ## 
%%
%[text] ## 

